"""Augmented reality: draws the weekly calendar next to an ArUco marker placed on the pillbox."""
import cv2
import numpy as np

from . import schedule

# Same colours in the AR overlay (BGR) and in the on-screen week view (hex)
STATUS_HEX = {schedule.NONE: "#3478C6", schedule.PENDING: "#D64545", schedule.DONE: "#2E9E5B"}
STATUS_BGR = {s: tuple(int(h[i:i + 2], 16) for i in (5, 3, 1)) for s, h in STATUS_HEX.items()}

MARKER_DICTIONARY = cv2.aruco.DICT_5X5_50


def load_calibration():
    """Camera matrix and distortion coefficients from camara.py (generated by calibrar.py), if present."""
    try:
        import camara
    except ImportError:
        return None, None
    return camara.cameraMatrix, camara.distCoeffs


class ARRenderer:
    def __init__(self, camera_matrix=None, dist_coeffs=None):
        dictionary = cv2.aruco.getPredefinedDictionary(MARKER_DICTIONARY)
        self.detector = cv2.aruco.ArucoDetector(dictionary, cv2.aruco.DetectorParameters())
        self.camera_matrix = camera_matrix
        self.dist_coeffs = dist_coeffs
        self._size = None
        self._maps = None
        self._roi = None

    def _rectify(self, frame):
        """Undistort with the calibration and crop to the valid region."""
        if self.camera_matrix is None:
            return frame
        h, w = frame.shape[:2]
        if self._size != (w, h):
            new_matrix, self._roi = cv2.getOptimalNewCameraMatrix(
                self.camera_matrix, self.dist_coeffs, (w, h), 1, (w, h))
            self._maps = cv2.initUndistortRectifyMap(
                self.camera_matrix, self.dist_coeffs, None, new_matrix, (w, h), cv2.CV_16SC2)
            self._size = (w, h)
        rectified = cv2.remap(frame, *self._maps, cv2.INTER_LINEAR)
        x, y, rw, rh = self._roi
        if rw > 0 and rh > 0:
            rectified = rectified[y:y + rh, x:x + rw]
        return np.ascontiguousarray(rectified)

    def render(self, frame, meds):
        """Return (frame with overlay, marker_found)."""
        frame = self._rectify(frame)
        corners, ids, _ = self.detector.detectMarkers(frame)
        if ids is None:
            return frame, False
        cv2.aruco.drawDetectedMarkers(frame, corners)
        draw_week(frame, corners, meds)
        return frame, True


def draw_week(frame, corners, meds, base_box_size=30, gap=6):
    """Draw one coloured box per weekday along the marker, warped to its perspective."""
    for corner in corners:
        top_left, top_right, bottom_right, bottom_left = corner[0]
        width = int(np.linalg.norm(top_right - top_left))
        height = int(np.linalg.norm(top_left - bottom_left))
        if width == 0 or height == 0:
            continue
        src = np.array([[0, 0], [width, 0], [width, height], [0, height]], dtype="float32")
        dst = np.array([top_left, top_right, bottom_right, bottom_left], dtype="float32")
        transform = cv2.getPerspectiveTransform(src, dst)

        box_size = int(base_box_size * width / 100.0)
        font_scale = max(0.4, box_size / 55)
        for j, (day, letter) in enumerate(zip(schedule.DAYS, schedule.DAY_LETTERS)):
            x0, y0 = 5, 5 + j * (box_size + gap)
            square = np.array([[[x0, y0], [x0 + box_size, y0], [x0 + box_size, y0 + box_size], [x0, y0 + box_size]]],
                              dtype="float32")
            points = cv2.perspectiveTransform(square, transform)[0].astype(int)
            cv2.fillPoly(frame, [points], STATUS_BGR[schedule.day_status(meds, day)])

            center_x = (points[0][0] + points[2][0]) // 2
            center_y = (points[0][1] + points[2][1]) // 2
            (text_w, text_h), _ = cv2.getTextSize(letter, cv2.FONT_HERSHEY_SIMPLEX, font_scale, 1)
            cv2.putText(frame, letter, (center_x - text_w // 2, center_y + text_h // 2),
                        cv2.FONT_HERSHEY_SIMPLEX, font_scale, (255, 255, 255), 1, cv2.LINE_AA)
    return frame
